            //
            aCross = (RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 904U)) & S_BLOCK1], 43U) ^ RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 606U)) & S_BLOCK1], 29U));
            aCross ^= RotL64(pCrossLaneA[((S_BLOCK1 - aIndex + 3818U)) & S_BLOCK1], 58U);
            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 39U) ^ RotL64(aPrevious, 5U)) + (RotL64(aCross, 57U) + RotL64(aIngress, 18U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
