            //
            aOrbiterI = ((aWandererG + RotL64(aIngress, 21U)) + RotL64(aCarry, 13U)) + 0x7C06D577D91431A0ULL;
            aOrbiterA = (aWandererE + RotL64(aScatter, 13U)) + 0xE978DEFBC5EA653DULL;
            aOrbiterH = ((aWandererH + RotL64(aPrevious, 41U)) + 0x6EB16B318F059922ULL) + aOASaltF[((aIndex + 486U)) & S_SALT1];
            aOrbiterG = (((aWandererJ + RotL64(aCross, 35U)) + RotL64(aCarry, 47U)) + 0xA0982DB8C7B42AE9ULL) + aOASaltA[((aIndex + 410U)) & S_SALT1];
            aOrbiterF = (aWandererK + RotL64(aIngress, 19U)) + 0x2C5F57BE042E5518ULL;
            aOrbiterK = (aWandererD + RotL64(aScatter, 60U)) + 0xCD8E9C6F44B7782FULL;
            aOrbiterJ = ((aWandererI + RotL64(aPrevious, 47U)) + 0x8E94261A4A1A06EAULL) + aOASaltD[(((511U - aIndex) + 320U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aCross, 51U)) + RotL64(aCarry, 23U)) + 0x4236C7E153C521C5ULL;
            aOrbiterE = (aWandererF + RotL64(aIngress, 37U)) + 0xA69DAC686CD1748AULL;
            aOrbiterC = ((aWandererA + RotL64(aScatter, 4U)) + 0xB6E2EA0F50468A6AULL) + aOASaltB[((aIndex + 239U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aPrevious, 29U)) + 0xB2C0F68AFBE31265ULL) + aOASaltC[((aIndex + 26U)) & S_SALT1];
            //
