            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x90BA822CE864DC63ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x44FCC98744A5AC0DULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xBB6E0299F45ACA28ULL;
