            aScatter = (RotL64(aCarry, 19U) ^ RotL64(aPrevious, 48U)) + (RotL64(aIngress, 3U) ^ RotL64(aCross, 35U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = ((aWandererA + RotL64(aIngress, 27U)) + RotL64(aCarry, 3U)) + 0x045886ACB33E28A5ULL;
            aOrbiterC = (aWandererE + RotL64(aScatter, 13U)) + 0x920F8C563C3311B7ULL;
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 60U)) + 0x3AF920A88FCF318CULL) + aOASaltD[(((511U - aIndex) + 280U)) & S_SALT1];
