            aOrbiterA = ((aWandererF + RotL64(aIngress, 29U)) + RotL64(aCarry, 11U)) + 0xFD594290144ADDCAULL;
            aOrbiterB = (aWandererI + RotL64(aScatter, 41U)) + 0x218F4B11D6AAB094ULL;
            aOrbiterE = (aWandererB + RotL64(aPrevious, 11U)) + 0xF0A91A25CA9010E4ULL;
            aOrbiterJ = ((aWandererK + RotL64(aCross, 23U)) + RotL64(aCarry, 19U)) + 0xDBB050348491048CULL;
            aOrbiterK = (aWandererH + RotL64(aIngress, 47U)) + 0xE103DD959101A76EULL;
            aOrbiterH = ((aWandererJ + RotL64(aScatter, 52U)) + 0x8E501783603088C4ULL) + aOASaltA[(((511U - aIndex) + 491U)) & S_SALT1];
            aOrbiterF = (aWandererC + RotL64(aPrevious, 43U)) + 0xF3C08A8B9EB80916ULL;
            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0x8A4E24D181A0A729ULL) + aOUSaltC[(((511U - aIndex) + 243U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0x68B9E20973D6E42BULL) ^ aOUSaltE[((aIndex + 176U)) & S_SALT1];
