            aOrbiterG = (((aWandererC + RotL64(aPrevious, 60U)) + RotL64(aCarry, 53U)) + 0xDBD9216CF6312853ULL) + aOASaltA[((aIndex + 408U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aCross, 19U)) + 0xBCDB08713D0EA941ULL;
            aOrbiterA = (aWandererA + RotL64(aIngress, 53U)) + 0x26BF987A9343C8C6ULL;
