            aOrbiterK = RotL64((aOrbiterK * 0xD6BA276CFAE2568DULL), 43U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x830CE2F455B8914CULL) + aOUSaltF[(((511U - aIndex) + 127U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x47E45BE608B982D1ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x4378D6021AF80CE1ULL), 29U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0xA47A7C2DDCC4B6F8ULL) + aOUSaltE[((aIndex + 232U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x6930BF8DE5496AE7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA333ED599D1A64EFULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x46EA878B34526F48ULL;
