            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x9DC16DC91A1CB83FULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x3135B18F49EE3D6CULL;
