            aWandererG = aWandererG + (((RotL64(aIngress, 19U) + aOrbiterJ) + RotL64(aOrbiterC, 43U)) + aWUSaltF[(((511U - aIndex) + 84U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aScatter, 48U) + aOrbiterG) + RotL64(aOrbiterE, 37U));
