            aOrbiterE = (((aWandererC + RotL64(aScatter, 27U)) + RotL64(aCarry, 23U)) + 0x82FD7A5BAA834F30ULL) + aOASaltH[(((511U - aIndex) + 402U)) & S_SALT1];
            aOrbiterF = ((aWandererH + RotL64(aPrevious, 51U)) + 0xB8860C64D2CC9F3AULL) + aOASaltC[(((511U - aIndex) + 187U)) & S_SALT1];
            aOrbiterC = (aWandererJ + RotL64(aCross, 43U)) + 0x74B0CB63431A5ACFULL;
            aOrbiterA = (aWandererD + RotL64(aIngress, 39U)) + 0xCE3865EBC782D698ULL;
            aOrbiterH = (((aWandererG + RotL64(aScatter, 47U)) + RotL64(aCarry, 19U)) + 0xA33F56D02586D231ULL) + aOASaltB[((aIndex + 173U)) & S_SALT1];
