            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0xCBDB75E88212BB99ULL) ^ aOUSaltF[(((511U - aIndex) + 508U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x0FD3B89EA7563D5DULL), 51U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0x89C62A0681CE9646ULL) + aOUSaltG[(((511U - aIndex) + 103U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x9F2712689458296BULL;
