            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x243D1D873ECEEFCEULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x24488F596FC8414CULL) ^ aOUSaltH[((aIndex + 392U)) & S_SALT1];
