            aWandererI = aWandererI + (((RotL64(aCross, 39U) + RotL64(aOrbiterI, 51U)) + aOrbiterB) + aWUSaltE[((aIndex + 399U)) & S_SALT1]);
            aWandererH = aWandererH ^ (((RotL64(aIngress, 27U) + RotL64(aOrbiterJ, 39U)) + aOrbiterD) + RotL64(aCarry, 39U));
