            aOrbiterF = (((aWandererK + RotL64(aScatter, 3U)) + RotL64(aCarry, 27U)) + 0x7D6A7A3950E8BF1EULL) + aOASaltG[(((511U - aIndex) + 505U)) & S_SALT1];
