            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xAF0E67663AC1540FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0xC987098D9724768DULL) ^ aOUSaltA[(((511U - aIndex) + 233U)) & S_SALT1];
