            aWandererG = aWandererG + ((RotL64(aIngress, 56U) + RotL64(aOrbiterF, 42U)) + aOrbiterI);
            aWandererB = aWandererB ^ (((RotL64(aScatter, 21U) + aOrbiterG) + RotL64(aOrbiterD, 57U)) + aWUSaltE[((aIndex + 307U)) & S_SALT1]);
