            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterB = (((aWandererB + RotL64(aIngress, 19U)) + RotL64(aCarry, 29U)) + 0x2877EB41F0B73D62ULL) + aOASaltC[(((511U - aIndex) + 84U)) & S_SALT1];
